using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var tools = new ResearchTools();

IChatClient client = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(tools.SearchWeb),
        AIFunctionFactory.Create(tools.SaveNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ]
};

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different queries).
        2. Saving important findings as notes using the SaveNote tool.
        3. After gathering enough information, retrieving your notes and providing a comprehensive summary.

        Be thorough but concise. Make at least 3 different searches to cover the topic well.
        Always save key findings as notes before summarizing.
        End with a well-structured summary of your research.
        """),
    new(ChatRole.User, $"Please research the following topic: {topic}")
];

Console.WriteLine("Agent is working...\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

// ---------------------------------------------------------------------------
// Tool implementations
// ---------------------------------------------------------------------------

partial class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _http = new();

    [Description("Search the web for information. Returns text snippets from search results.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  \U0001F50D Searching: {query}");
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var resp = await _http.SendAsync(request);
            var html = await resp.Content.ReadAsStringAsync();

            var snippets = new List<string>();
            foreach (Match m in SnippetRegex().Matches(html))
            {
                var text = StripHtml(m.Groups[1].Value).Trim();
                if (!string.IsNullOrWhiteSpace(text))
                    snippets.Add(text);
            }

            if (snippets.Count == 0)
                return "No results found for this query.";

            var sb = new StringBuilder();
            foreach (var s in snippets.Take(8))
                sb.AppendLine($"- {s}");
            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record important findings.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  \U0001F4DD Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  \U0001F4CB Retrieved {_notes.Count} note(s)");
        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i]}");
        return sb.ToString();
    }

    private static string StripHtml(string html) =>
        TagRegex().Replace(WebUtility.HtmlDecode(html), "");

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex TagRegex();

    [GeneratedRegex(
        @"class=""result__snippet""[^>]*>(.*?)</a>",
        RegexOptions.Singleline)]
    private static partial Regex SnippetRegex();
}

